#!/usr/bin/env python3
"""Render truthful per-batch reports from executed machine evidence."""
import argparse
from pipeline import ROOT, COUNTS, read


def run(batch):
    dest=ROOT/f'batch-{batch}'
    cov=read(dest/'coverage.json')
    verify=read(dest/'verification.json')
    rebuild=read(dest/'reproducibility.json')
    browser=read(dest/'browser.json') if (dest/'browser.json').exists() else {'status':'PENDING','capture_count':0}
    layout=read(dest/'proof-layout.json')
    new=read(dest/'catalog-delta.json')['assets']
    names='\n'.join(f'- `{a["id"]}` — {a["name"]} ({a["category"]}; {a["kind"]})' for a in new)
    demand='All 12 are **evidence-free for this account: 0 observed rows**. General coverage for other users only; not observed-demand items. The historical proposal\'s ingredient-level mention for grilled squid did not resolve to this identity; it was sushi. Owner amendment supersedes reserve/demand prose in the frozen reference.' if batch==5 else 'Observed and zero-observed additions are separately listed in `coverage.json`. This is not a claim that every new identity was logged.'
    alias='''\n## Alias versus dedicated study — honesty decision\n\n- `pad-thai`: dedicated generic study, with orange flat strands, a lime wedge, sprouts and restrained peanut/shrimp cues. Those durable cues honestly distinguish the named dish from the shipped generic stir-fried-noodles bowl. Its label, not the image alone, names the class; it makes no assertion about a logged recipe, protein, portion or allergy. No shipped aliases changed.\n- `boba-tea`: dedicated pearl-focused clear-cup study, broad straw and visible bottom pearl mass. The earlier `milk-tea` study depicts orange Thai-style tea and keeps its approved `bubble tea` alias. This overlap is intentional generic coverage, not a claim of perfect name disambiguation. A future matcher/bundling lane must retain exact-ID/name priority and test both names. No shipped identities or aliases were rewritten.\n\nBoth decisions use recognizable, honest generic depictions rather than reduced authoring effort.\n''' if batch==5 else ''
    report=f'''# Issue 262 · batch {batch}\n\nDESIGN ARTIFACTS ONLY — subject list approved; final pixels await owner review. No per-batch stop (owner decision); no app integration or rollout.\n\n## Delivered\n\n{COUNTS[batch]} new food identities{', plus five approved labeled category fallbacks' if batch==1 else ''}. Cumulative candidate: **{verify['food_count']} foods**, {verify['fallback_count']} fallback signs; {verify['asset_count']} assets total. Shipped baseline is 13 foods plus five fallbacks (including neutral), not 14 foods.\n\n{names}\n\n## Proofs\n\n- [Paper contact sheet](contact-paper.png) / [Night contact sheet](contact-night.png)\n- [Both themes at native 64px and diagnostic 40px](optical-both.png)\n- [Paper phone strip](proofs/phone-all-paper.png) / [Night phone strip](proofs/phone-all-night.png)\n- [Interactive Paper gallery](gallery-paper.html) / [Night gallery](gallery-night.html)\n- [Catalog delta](catalog-delta.json), [subjects](subjects.json), [build cache](build-cache.json), [SHA-256 manifest](SHA256SUMS.json)\n\nPhone proof pages: {len(layout['cohorts'])} cohorts per theme, 390×844 CSS/device pixels, every new ID at exactly 64×64 pixels. Layout is fictional and labeled; not a screenshot of deployed/native Morsel. 40px is diagnostic only.\n\n## Coverage — observed data versus general coverage\n\n{demand}\n\nFrozen observation window: {cov['distinct_names']} distinct names / {cov['total_rows']} rows. The estimate uses the approved round-1 qualifier-tolerant estimator, **not the shipped #260 resolver**. {'Private local aggregate was recomputed for this delivery' if cov['reference_recomputed_against_private_input'] else 'Frozen aggregate reused; private observation data was not available for recomputation in this run'}; raw names never enter this bundle.\n\n| Partition | Distinct names | Rows |\n|---|---:|---:|\n| Specific studies now available | {cov['specific']['distinct']} ({cov['specific']['distinct_pct']}%) | {cov['specific']['rows']} ({cov['specific']['rows_pct']}%) |\n| Labeled category fallback | {cov['category_fallback']['distinct']} | {cov['category_fallback']['rows']} |\n| Neutral | {cov['neutral']['distinct']} | {cov['neutral']['rows']} |\n| Specific study pending a later batch | {cov['pending_later_studies']['distinct']} | {cov['pending_later_studies']['rows']} |\n\nThis batch changes estimated specific coverage by {cov['specific_delta_distinct']} distinct names / {cov['specific_delta_rows']} rows. Pending-later entries are shown explicitly so the partition closes; they are not silently presented as covered. The named pork-gravy / Chinese-kale / linguine classes have specific studies from batch 1. Rice and coffee reuse their unchanged shipped studies. Actual runtime matching remains an implementation-lane check.\n{alias}\n## Executed verification\n\n- Asset gate: {verify['status']}, raw exit {verify['raw_exit']}. Closed-set IDs, source/master parity, locked palette, transparent RGBA dimensions, border/alpha checks, cache output hashes.\n- Shipped preservation: 18 identities × nine art files = 162 before/after SHA-256 comparisons; full product baseline covers {verify['protected_product_files']} files (shipped art/docs plus app/DB/schema). Each pair is recorded in [shipped-18-before-after.json](shipped-18-before-after.json). Original catalog entries, aliases, fonts and shared wash are unchanged.\n- Clean rebuild: {rebuild['status']}, raw exit {rebuild['raw_exit']}; **{rebuild['files_compared']}** new master/export files recreated in fresh scratch without cache, byte-identical SHA-256. See [reproducibility.json](reproducibility.json).\n- Browser gate: {browser['status']}; {browser['capture_count']} actual Chromium screenshots with image/font load, console, no-overflow, 44px links, all-row visibility, exact 64px placement and all-ID/both-theme coverage. See [browser.json](browser.json).\n- Public-package private-name scan and manifests: see `privacy.json` and `SHA256SUMS.json` after final packaging.\n- Visual judgment: see `VISUAL-REVIEW.md`; mechanical passes are not owner approval.\n\n## Reproduce / limitations\n\nSee [root README](../README.md). New source SVGs are original agent-authored on gpt-6-astra. Exact clean export bytes depend on the pinned recorded librsvg/cairo environment; no runtime generation. Historical raw observations are private, so public clones can verify aggregate hashes but cannot independently requery account history. Shipped pixels and app resources are never regenerated or wired by this pipeline.\n\nDESIGN ARTIFACTS ONLY; no app/DB edits; not merged; not opened as PR; no deploy.\n'''
    report += '\n## Repository gate caveat\n\nSee [HOST-GATES.md](../HOST-GATES.md). npm ci, typecheck, lint and diff-check exited 0. The one npm test invocation exited 1: 583 passed / 2 failed, both 5000ms timeouts in unchanged server files, plus two worker timeouts. No retries, timeout changes, skipped tests or hosted-CI success claim. Asset/browser/rebuild gates above are separate from that raw aggregate result.\n'
    (dest/'BATCH-REPORT.md').write_text(report)
    print(f'Wrote batch {batch} report from real gate files; browser {browser["status"]}')


if __name__=='__main__':
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--batch',type=int,choices=range(1,6),required=True)
    run(ap.parse_args().batch)
